sys_variable_value.value:
(function execute(inputs, outputs) {
    var fieldList = [];
    var gr = inputs.record;

    // 1. Verify Input exists
    if (!gr) {
        gs.info("DEBUG: inputs.record is null or undefined");
    } else if (!gr.isValidRecord()) {
        gs.info("DEBUG: inputs.record is NOT a valid GlideRecord object. Check if Input Type is 'Reference'.");
    } else {
        gs.info("DEBUG: Successfully received record from table: " + gr.getTableName());
        
        // 2. Use getElements() for Scoped safety
        var fields = gr.getElements(); 
        gs.info("DEBUG: Total elements found on record: " + fields.length);

        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            var name = field.getName();

            // 3. Trace Custom Field Filter
            if (name.startsWith('u_')) {
                var isNil = field.nil();
                var isProcessed = (name === 'u_ai_processed');
                
                if (!isNil && !isProcessed) {
                    gs.info("DEBUG: Found Match! Adding field: " + name);
                    fieldList.push(name);
                } else {
                    // This will tell you WHY a u_ field was skipped
                    gs.info("DEBUG: Skipping " + name + " | Reason: " + (isNil ? "EMPTY/NIL" : "AI_PROCESSED_FLAG"));
                }
            }
        }
    }

    gs.info("DEBUG: Final Field List Count: " + fieldList.length);
    outputs.field_list = fieldList;

})(inputs, outputs);

